APP_ROLE = "caderneta_app"

# Tabelas isoladas pela regra padrão: só linhas da escola do perfil ativo.
TABELAS_ESCOLA = [
    "ano_letivo", "periodo", "disciplina", "turma", "atribuicao", "aluno", "matricula",
    "vinculo_responsavel", "ficha_saude",
]


def _seguranca() -> None:
    op.execute("""
    CREATE FUNCTION app_escola() RETURNS uuid LANGUAGE sql STABLE AS
      $$ SELECT nullif(current_setting('app.escola_id', true), '')::uuid $$;
    CREATE FUNCTION app_usuario() RETURNS uuid LANGUAGE sql STABLE AS
      $$ SELECT nullif(current_setting('app.usuario_id', true), '')::uuid $$;
    """)
    op.execute(f"GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO {APP_ROLE}")
    op.execute(f"REVOKE ALL ON alembic_version FROM {APP_ROLE}")
    # Escolas são criadas pela CLI (papel dono); auditoria é só inserção.
    op.execute(f"REVOKE INSERT, DELETE ON escola FROM {APP_ROLE}")
    op.execute(f"REVOKE UPDATE, DELETE ON auditoria FROM {APP_ROLE}")

    for t in TABELAS_ESCOLA:
        op.execute(f"ALTER TABLE {t} ENABLE ROW LEVEL SECURITY")
        op.execute(
            f"CREATE POLICY isolamento ON {t} USING (escola_id = app_escola()) "
            f"WITH CHECK (escola_id = app_escola())"
        )

    op.execute("""
    ALTER TABLE escola ENABLE ROW LEVEL SECURITY;
    CREATE POLICY isolamento ON escola USING (
      id = app_escola()
      OR id IN (SELECT escola_id FROM usuario_perfil WHERE usuario_id = app_usuario())
    );

    -- Perfis: os da escola ativa, e os do próprio usuário (para trocar de escola/perfil).
    ALTER TABLE usuario_perfil ENABLE ROW LEVEL SECURITY;
    CREATE POLICY isolamento ON usuario_perfil
      USING (escola_id = app_escola() OR usuario_id = app_usuario())
      WITH CHECK (escola_id = app_escola());

    -- Usuários: o próprio, quem tem perfil ou vínculo na escola ativa, e o e-mail em processo de login.
    ALTER TABLE usuario ENABLE ROW LEVEL SECURITY;
    CREATE POLICY leitura ON usuario FOR SELECT USING (
      id = app_usuario()
      OR email = nullif(current_setting('app.login_email', true), '')
      OR id IN (SELECT usuario_id FROM usuario_perfil WHERE escola_id = app_escola())
      OR id IN (SELECT usuario_id FROM vinculo_responsavel WHERE escola_id = app_escola())
    );
    CREATE POLICY criacao ON usuario FOR INSERT WITH CHECK (id = app_usuario());
    CREATE POLICY alteracao ON usuario FOR UPDATE USING (id = app_usuario());

    -- Convites: os da escola ativa, ou aquele cujo token está sendo usado agora.
    ALTER TABLE convite ENABLE ROW LEVEL SECURITY;
    CREATE POLICY isolamento ON convite
      USING (escola_id = app_escola()
             OR token_hash = nullif(current_setting('app.convite_token', true), ''))
      WITH CHECK (escola_id = app_escola());

    ALTER TABLE auditoria ENABLE ROW LEVEL SECURITY;
    CREATE POLICY leitura ON auditoria FOR SELECT USING (escola_id = app_escola());
    CREATE POLICY insercao ON auditoria FOR INSERT
      WITH CHECK (escola_id IS NULL OR escola_id = app_escola());

    -- Sessões e tokens de senha só guardam hashes; acessados apenas pelo hash do token.
    """)
